 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # Bottom-edge cells mark the vertical tracks. Each track crosses
    # horizontal bands at their one-cell gaps.
    for c in range(w):
        marker = g[h - 1][c]
        if marker == 0:
            continue
        crossings = []
        for r in range(h):
            if g[r][c] != 0:
                continue
            left = next((g[r][x] for x in range(c - 1, -1, -1) if g[r][x] != 0), 0)
            right = next((g[r][x] for x in range(c + 1, w) if g[r][x] != 0), 0)
            if left and left == right:
                crossings.append((r, left))
        if not crossings:
            continue
        crossings.sort()
        # Above and through the first band, use its color. Each later band
        # colors the segment after the preceding crossing through itself;
        # the bottom marker colors everything below the final band.
        first_r, first_color = crossings[0]
        for r in range(0, first_r + 1):
            g[r][c] = first_color
        for (prev_r, _), (next_r, next_color) in zip(crossings, crossings[1:]):
            for r in range(prev_r + 1, next_r + 1):
                g[r][c] = next_color
        last_r = crossings[-1][0]
        for r in range(last_r + 1, h):
            g[r][c] = marker
    return g
